pub(super) fn test_arm_shared_neon_vst1_lane_p16() -> Result<(), String> {
    unsafe {
        let mut ptr_a = crate::cpu::common::Aligned64([1u16; 64]);
        let b = create_poly16x4_t_from([2, 3, 4, 5]);
        vst1_lane_p16::<0>(ptr_a.0.as_mut_ptr(), b);
    }
    Ok(())
}

