        check_float_array_equality(&result, &[-10.0, -10.0]).map_err(|e| format!("{e} | call: vsub_f32(create_float32x2_t_from([0.0f32, -1.0f32]), create_float32x2_t_from([10.0f32, 9.0f32]))"))?;

